from ..widgets.widgets import BetterCanvas
from ..widgets.widgets import Tooltip
from ..utils.logger import logger

import tkinter as tk
import itertools
from tkinter import ttk

from PIL import Image, ImageTk
from pathlib import Path
import os


class BBModsFrame(ttk.Frame):

    def __init__(self, parent, model, *args, **kwargs):
        super().__init__(parent, name="bbmod_frame_section", borderwidth=1, relief="ridge", *args, **kwargs)
        self.available_bbmods = list(model.bbmods_smods_info['BBMODS'])
        self.bbmods_dictionary = {}
        self.bbmods_iterator = 1
        self.icons = self.__get_icons()
        self._initial_setup()

    def get_bbmods(self):
        return self.bbmods_dictionary

    def get_configuration(self):
        return {k: v.get_bbmod() for k, v in sorted(self.bbmods_dictionary.items(), key=lambda item: item[0]) if v.is_configured}

    def _initial_setup(self):
        bbmods_label = ttk.Label(
            self, text="BBMOD TYPE", font=('Helvetica', 12, 'bold'), name='bbmod_frame_label'
        )
        add_new_bbmod_button = ttk.Button(
            self, text='Add BBMOD', command=lambda: self._add_bbmod(event=True), image=self.icons['bbmod_plus'], name='add_bbmod_frame'
        )
        Tooltip(add_new_bbmod_button, text='Add BBMOD')
        separator = ttk.Separator(
            self, orient='horizontal', name="header_separator"
        )
        bbmods_canvas = BetterCanvas(
            self, bg="white", borderwidth=0, height=400, name="bbmods_canvas", width=210
        )
        bbmods_scrollbar = ttk.Scrollbar(
            self, orient=tk.VERTICAL, command=bbmods_canvas.yview, name="bbmods_scrollbar"
        )
        bbmods_frame = ttk.Frame(
            bbmods_canvas, name="bbmods_frame"
        )
        bbmods_canvas.create_window((0, 0), window=bbmods_frame)
        bbmods_canvas.configure(yscrollcommand=bbmods_scrollbar.set)

        bbmods_label.grid(column=0, row=0, sticky="sw", padx=(14, 0), ipady=10, columnspan=2)
        add_new_bbmod_button.grid(row=0, column=2, padx=(0, 0), sticky="se")
        separator.grid(row=1, sticky="ew", columnspan=3)
        bbmods_canvas.grid(row=2, sticky="sew", columnspan=3)
        bbmods_scrollbar.grid(row=2, column=2, sticky="nse")

        def update_canvas(_event):
            bbmods_canvas.configure(scrollregion=bbmods_canvas.bbox("all"))
            if bbmods_canvas.yview() == (0.0, 1.0):
                bbmods_canvas.yview_moveto(1.0)
        bbmods_frame.bind("<Configure>", update_canvas)  # is it necessary?

        bbmods_canvas.bind('<Enter>', self._bound_to_mousewheel)
        bbmods_canvas.bind('<Leave>', self._unbound_to_mousewheel)

    @property
    def bbmods_canvas(self):
        return self.children['bbmods_canvas']

    @property
    def bbmods_scrollbar(self):
        return self.children['bbmods_scrollbar']

    def _bound_to_mousewheel(self, _event):
        self.bbmods_canvas.bind_all("<Button-4>", lambda event: self.bbmods_canvas.yview_scroll(int(-1 * event.num), 'units'))
        self.bbmods_canvas.bind_all("<Button-5>", lambda event: self.bbmods_canvas.yview_scroll(int(event.num), 'units'))

    def _unbound_to_mousewheel(self, _event):
        self.bbmods_canvas.unbind_all("<Button-4>")
        self.bbmods_canvas.unbind_all("<Button-5>")

    def _add_bbmod(self, bbmod_name='', event=False):
        number_of_bbmods = len(self.bbmods_dictionary)
        next_bbmod_id = number_of_bbmods + 1

        parent = self.children['bbmods_canvas'].children['bbmods_frame']
        single_bbmod_frame = SingleBBModFrame(
            parent, bbmod_name, self.available_bbmods, self.icons, text=f"BBMOD-{next_bbmod_id}", borderwidth=0,
            font=('Helvetica 9'), bg='white', name=f"bbmod_{self.bbmods_iterator}_frame"
        )
        self.bbmods_dictionary[next_bbmod_id] = single_bbmod_frame
        single_bbmod_frame.grid(column=1, row=next_bbmod_id, columnspan=2)
        self.bbmods_iterator += 1
        if event:
            self.event_generate('<<PostAddBbmod>>')
            logger.info(f"Adding BBMOD to {self}")

    def reset(self):
        new_bbmods_dictionary = {}
        for i, bbmod in sorted(self.bbmods_dictionary.items(), key=lambda item: item[0]):
            if i == 1:
                bbmod._reset()
                new_bbmods_dictionary[1] = bbmod
            else:
                bbmod.destroy()
        self.bbmods_dictionary = new_bbmods_dictionary

    def full_reset(self):
        self.reset()
        if 1 in self.bbmods_dictionary:
            bb = self.bbmods_dictionary.pop(1)
            bb.forget()
            bb.destroy()
        self.rearrange()

    def rearrange(self):
        new_bbmods_dictionary = {}
        for i, (idx, bbmod) in zip(itertools.count(1), sorted(self.bbmods_dictionary.items(), key=lambda item: item[0])):
            bbmod.grid(row=i, sticky="new", column=0, columnspan=2)
            new_bbmods_dictionary[i] = bbmod
            bbmod.configure(text=f"BBMOD-{i}")
        self.bbmods_scrollbar.set(0, 1)
        self.bbmods_dictionary = new_bbmods_dictionary

    def get_validation_log(self):
        return [f"BBMOD-{k} is not configured" for k, v in sorted(self.bbmods_dictionary.items(), key=lambda item: item[0]) if not v.is_configured]

    def __get_icons(self):
        graphic_src_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"

        bbmod_plus = Image.open(graphic_src_path / "bbmod_plus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        bbmod_plus_image = ImageTk.PhotoImage(bbmod_plus, master=self)

        minus_sign = Image.open(graphic_src_path / "large_minus.png").convert(mode='RGBA').resize((24, 24), Image.ANTIALIAS)
        minus_sign_image = ImageTk.PhotoImage(minus_sign)

        return {
            'bbmod_plus': bbmod_plus_image,
            'bbmod_minus': minus_sign_image,
        }


class SingleBBModFrame(tk.LabelFrame):
    def __init__(self, parent, bbmod_name, available_bbmods, icons, **kwargs):
        super().__init__(parent, labelanchor="nw", **kwargs)
        self.available_bbmods = available_bbmods
        self.icons = icons
        self._initial_setup(bbmod_name)

    @property
    def is_configured(self):
        return bool(self.children['additonal_bbmod_frame'].children['bbmod_combobox'].get())

    def get_bbmod(self):
        return self.children['additonal_bbmod_frame'].children['bbmod_combobox'].get()

    def _initial_setup(self, bbmod_name):
        single_frame = ttk.Frame(
            self, name='additonal_bbmod_frame'
        )
        bbmod_combobox = ttk.Combobox(
            single_frame, values=self.available_bbmods, width=12, state="readonly", name="bbmod_combobox",
        )
        bbmod_combobox.set(bbmod_name)
        Tooltip(bbmod_combobox, text='Set BBMOD')
        delete_bbmod_button = ttk.Button(
            single_frame, text="Delete BBMOD", name="delete_bbmod", command=lambda: self._destroy_bbmod(), image=self.icons['bbmod_minus']
        )
        Tooltip(delete_bbmod_button, text='Delete/Reset BBMOD')
        single_frame.grid(row=0, column=0, columnspan=3)
        separator_h = ttk.Separator(self, orient='horizontal')
        bbmod_combobox.grid(row=0, column=0, columnspan=2)
        delete_bbmod_button.grid(row=0, column=2, padx=(20, 0))
        separator_h.grid(row=1, sticky="ew", columnspan=4)

    def get_choosen_bbmod(self):
        return self.children['additonal_bbmod_frame'].children['bbmod_combobox'].get()

    def _destroy_bbmod(self):
        self.event_generate('<<PriorDeleteBbmod>>')
        number_of_configured_bbmods = len(self.__get_bbmods_frame().bbmods_dictionary)
        if number_of_configured_bbmods > 1:
            logger.info(f"Deleting BBMOD {self}")
            self._destroy()
        else:
            logger.info(f"Reseting BBMOD {self}")
            self._reset()
            self.event_generate('<<PostDeleteBbmod>>')

    def _destroy(self, event=True):
        configured_bbmods = self.__get_bbmods_frame().bbmods_dictionary
        current_id = self._get_current_id(configured_bbmods)
        configured_bbmods.pop(current_id)
        self.forget()
        self.__get_bbmods_frame().rearrange()
        if event:
            self.event_generate('<<PostDeleteBbmod>>')
        self.destroy()

    def _reset(self):
        self.children['additonal_bbmod_frame'].children['bbmod_combobox'].set("")

    def _get_current_id(self, connections):
        for id_, connection in connections.items():
            if connection == self:
                return id_

    def __get_bbmods_frame(self):
        return self.master.master.master
